using Check=std::function<void(bool,const char*)>;
class ActivationBlock {HHOOK hook_;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int n,WPARAM w,LPARAM l)->LRESULT{return n==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate image precision fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
sct::core::Image Pixels(int width=80,int height=60,COLORREF color=RGB(255,255,255)){sct::core::Image image;image.Create(width,height);for(size_t i=0;i<image.pixels.size();i+=4){image.pixels[i]=GetBValue(color);image.pixels[i+1]=GetGValue(color);image.pixels[i+2]=GetRValue(color);image.pixels[i+3]=255;}return image;}
sct::core::DocumentState Source(){using namespace sct::core;auto state=Document(Pixels(320,220)).State();Annotation a;a.tool=Tool::Rectangle;a.rect={20,20,80,70};state.objects.push_back(a);return state;}
void Core(Check check,const std::filesystem::path& dir){using namespace sct;CString error;
    for(auto ratio:{std::pair<int,int>{1,1},{4,3},{16,9}})for(auto pointer:{POINT{170,130},POINT{-500,-200},POINT{500,500}}){const auto r=core::RatioCrop({100,80},pointer,ratio.first,ratio.second,320,220);check(core::CropBounds(r,320,220)&&std::abs((r.right-r.left)*ratio.second-(r.bottom-r.top)*ratio.first)<=std::max(ratio.first,ratio.second),"ratio crop remains in canvas in every quadrant with bounded pixel rounding");}
    const RECT before{80,60,160,120};for(int handle=0;handle<9;++handle)if(handle!=4){const auto r=core::ResizeRatioCrop(before,handle,{110,90},4,3,320,220);check(core::CropBounds(r,320,220)&&std::abs((r.right-r.left)*3-(r.bottom-r.top)*4)<=4,"all eight crop handles preserve ratio and valid image bounds");}
    check(!core::CropBounds({-1,0,20,20},80,60)&&!core::CropBounds({0,0,81,60},80,60)&&!core::CropBounds({1,1,1,5},80,60),"numeric crop rejects negative/outside/empty rectangles");bool rejected=false;try{core::RatioCrop({0,0},{50,50},0,1,320,220);}catch(const std::exception&){rejected=true;}check(rejected,"zero/incomplete ratio rejects rather than divides by zero");
    auto source=Pixels();for(double angle:{0.,90.,-90.,180.,360.}){const auto actual=core::RotateAngle(source,angle,true,RGB(255,255,255),true),expected=core::Rotate(source,static_cast<int>(std::lround(angle/90.)));check(actual.width==expected.width&&actual.height==expected.height&&actual.pixels==expected.pixels,"quarter rotations use exact existing pixel mapping including zero/full turn");}
    auto rotated=core::RotateAngle(source,30.5,true,RGB(12,34,56),true);check(rotated.width>source.width&&rotated.height>source.height&&rotated.Row(0)[3]==0,"fractional expanded rotation keeps transparent outer corners");auto opaque=core::RotateAngle(source,-30.5,false,RGB(12,34,56),false);check(opaque.width==80&&opaque.height==60&&opaque.Row(0)[0]==56&&opaque.Row(0)[1]==34&&opaque.Row(0)[2]==12&&opaque.Row(0)[3]==255,"fixed-canvas rotation retains dimensions and chosen opaque corner fill");for(double angle:{361.,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()})check(core::RotateAngle(source,angle,true,0,true).Empty(),"out-of-range and non-finite rotations reject safely");auto damaged=source;damaged.pixels.resize(1);check(core::RotateAngle(damaged,15,true,0,true).Empty(),"rotation validates pixel storage before borrowing GDI buffer");
    services::ImageComparison comparison;check(services::CompareImages(source,source,comparison,error)&&comparison.changed==0&&comparison.total==4800,"identical comparison reports exact zero difference");auto after=source;after.Row(5)[7*4+3]=254;check(services::CompareImages(source,after,comparison,error)&&comparison.changed==1&&comparison.difference.Row(5)[7*4+2]==240,"RGBA comparison detects alpha-only change and marks its exact pixel");check(services::CompareImages(source,Pixels(81,60),comparison,error)&&comparison.changed==60&&comparison.total==4860,"different dimensions mark the nonoverlapping column without stretching");const auto retained=comparison.changed;check(!services::CompareImages(damaged,source,comparison,error)&&comparison.changed==retained,"malformed comparison input preserves previous output transactionally");auto a=Source(),b=a;b.objects.clear();check(services::CompareDocuments(a,b,comparison,error)&&comparison.changed>0&&a.objects.size()==1&&b.objects.empty(),"document comparison renders annotations without modifying either source");auto huge=std::make_shared<core::Image>();huge->width=huge->height=32768;a.base=huge;check(!services::CompareDocuments(a,b,comparison,error),"comparison aggregate buffer budget rejects before huge rendering allocation");
    core::Document document(Pixels());for(int i=1;i<=8;++i){auto s=document.State();core::Annotation object;object.tool=core::Tool::Rectangle;object.rect={i,i,i+2,i+2};s.objects.push_back(object);document.Commit(s);}check(document.UndoCount()==8&&document.HistoryState(-8)->objects.empty()&&document.HistoryState(-1)->objects.size()==7,"RAM history metadata exposes chronological immutable snapshots");check(document.NavigateHistory(-5)&&document.State().objects.size()==3&&document.RedoCount()==5&&document.UndoCount()==3,"multi-step history jump preserves exact redo order");check(document.NavigateHistory(4)&&document.State().objects.size()==7&&document.RedoCount()==1&&document.UndoCount()==7,"forward jump restores intervening states without duplicating history");const auto undo=document.UndoCount(),redo=document.RedoCount();check(!document.NavigateHistory(-99)&&!document.NavigateHistory(99)&&!document.NavigateHistory(0)&&document.UndoCount()==undo&&document.RedoCount()==redo,"invalid/no-op navigation preserves all logical history");check(document.Undo()&&document.State().objects.size()==6&&document.Redo()&&document.State().objects.size()==7,"ordinary undo/redo retains exact one-step behavior");auto changed=document.State();changed.objects.clear();document.Commit(changed);check(!document.RedoCount(),"new commit after timeline navigation clears only obsolete redo branch");for(int i=0;i<25;++i)document.Commit(document.State());check(document.UndoCount()==20,"timeline retains existing twenty-state history limit");document.ClearHistory();check(!document.UndoCount()&&!document.RedoCount()&&!document.HistoryState(-1),"explicit clear removes only undo metadata and leaves current state");services::ProcessResources process;check(services::ReadProcessResources(process)&&process.working>0&&process.privateBytes>0&&process.peakWorking>=process.working,"own-process metrics expose actual working/private/peak samples separately from estimates");std::vector<BYTE> encoded;check(services::EncodeImage(rotated,L"png",100,encoded,error)&&services::WriteBytes((dir/L"rotation-fractional.png").c_str(),encoded,error),"fractional rotation pixel evidence stays in test artifacts");
}
